package com.graden.editor.cinema;
import java.util.*;
public final class FocusTrack {
 public interface Source{int size();ClipCache.Feature feature(int i)throws Exception;}
 public static class Result{public float[] focus,x,y,confidence;public List<Subject>[] candidates;public boolean[] cut;Result(int n){candidates=(List<Subject>[])new List<?>[n];focus=new float[n];x=new float[n];y=new float[n];confidence=new float[n];cut=new boolean[n];}}
 public static float ease(float t){t=Math.max(0,Math.min(1,t));return t*t*t*(t*(6*t-15)+10);}
 public static class Subject{public int id,kind=-1;public float left,top,right,bottom;public float x,y,d,score;Subject(float x,float y,float d,float s){this.x=x;this.y=y;this.d=d;score=s;}}
 /** People first, then animals, then things that move; other objects last. Ranks are ours, not Apple's, whose are private. */
 static float kindWeight(int c){if(c==0)return 3;if(c>=14&&c<=23)return 2.5f;if(c>=1&&c<=8)return 1.3f;return 1;}
 /** Real detections when there are any: each box's depth is the middle of what fills it. */
 static List<Subject> detected(ClipCache.Feature f){ArrayList<Subject> out=new ArrayList<>();for(int k=0;k+5<f.boxes.length;k+=6){int c=(int)f.boxes[k];float l=f.boxes[k+2],t=f.boxes[k+3],r=f.boxes[k+4],b=f.boxes[k+5];int x0=Math.max(0,(int)((l+(r-l)*.25f)*f.width)),x1=Math.min(f.width-1,(int)((r-(r-l)*.25f)*f.width)),y0=Math.max(0,(int)((t+(b-t)*.2f)*f.height)),y1=Math.min(f.height-1,(int)((b-(b-t)*.2f)*f.height));float[] v=new float[Math.max(1,(x1-x0+1)*(y1-y0+1))];int n=0,solid=0;for(int y=y0;y<=y1;y++)for(int x=x0;x<=x1;x++)if(c==0&&(f.alpha[y*f.width+x]&255)>145)solid++;for(int y=y0;y<=y1;y++)for(int x=x0;x<=x1;x++){int i=y*f.width+x;if(solid<4||c!=0||(f.alpha[i]&255)>145)v[n++]=f.depth[i];}if(n==0)continue;Arrays.sort(v,0,n);float d=v[n/2],x=(l+r)/2,y=(t+b)/2,area=(r-l)*(b-t)*f.width*f.height;Subject s=new Subject(x,y,d,area*(1-.5f*Math.abs(x-.5f))*(1+.5f*d)*kindWeight(c)*f.boxes[k+1]+2);s.kind=c;s.left=l;s.top=t;s.right=r;s.bottom=b;out.add(s);}out.sort((p,q)->Float.compare(q.score,p.score));return out;}
 public static List<Subject> subjects(ClipCache.Feature f){if(f.boxes.length>0){List<Subject> real=detected(f);if(!real.isEmpty())return real;}ArrayList<Subject> out=new ArrayList<>();int n=f.depth.length;boolean[] seen=new boolean[n];int[] q=new int[n];
 for(int seed=0;seed<n;seed++){if(seen[seed])continue;boolean person=(f.alpha[seed]&255)>145;int head=0,tail=1;q[0]=seed;seen[seed]=true;int minx=f.width,miny=f.height,maxx=0,maxy=0;float sx=0,sy=0,sd=0;float anchor=f.depth[seed];
 while(head<tail){int i=q[head++],x=i%f.width,y=i/f.width;minx=Math.min(minx,x);maxx=Math.max(maxx,x);miny=Math.min(miny,y);maxy=Math.max(maxy,y);sx+=x;sy+=y;sd+=f.depth[i];int[] ns={x>0?i-1:-1,x+1<f.width?i+1:-1,y>0?i-f.width:-1,y+1<f.height?i+f.width:-1};for(int j:ns)if(j>=0&&!seen[j]&&((f.alpha[j]&255)>145)==person&&Math.abs(f.depth[j]-anchor)<.065){seen[j]=true;q[tail++]=j;}}
 if(tail>n*.008&&tail<n*.65&&(person||anchor>.18)){float x=sx/tail/(f.width-1),y=sy/tail/(f.height-1),d=sd/tail;Subject v=new Subject(x,y,d,tail*(1-.5f*Math.abs(x-.5f))*(1+.5f*d)*(person?1.5f:1));v.left=minx/(float)f.width;v.right=(maxx+1f)/f.width;v.top=miny/(float)f.height;v.bottom=(maxy+1f)/f.height;out.add(v);}}
 out.sort((x,y)->Float.compare(y.score,x.score));if(out.size()>12)out=new ArrayList<>(out.subList(0,12));if(out.isEmpty()){Subject v=new Subject(.5f,.5f,f.at(.5f,.5f),1);v.left=.4f;v.top=.4f;v.right=.6f;v.bottom=.6f;out.add(v);}return out;}
 public static float curve(float t,float a,float b){t=Math.max(0,Math.min(1,t));a=Math.max(0,Math.min(1,a));b=Math.max(a,Math.min(1,b));float u=1-t;return 3*u*u*t*a+3*u*t*t*b+t*t*t;}
 static float dist(float x,float y,Subject s){return (x-s.x)*(x-s.x)+(y-s.y)*(y-s.y);}
 static float score(ClipCache.Feature a,int ax,int ay,ClipCache.Feature b,int bx,int by){double sa=0,sb=0,saa=0,sbb=0,sab=0;int n=0;for(int y=-4;y<=4;y++)for(int x=-4;x<=4;x++){int xx=ax+x,yy=ay+y,u=bx+x,v=by+y;if(xx<0||xx>=a.width||yy<0||yy>=a.height||u<0||u>=b.width||v<0||v>=b.height)continue;double va=a.gray[yy*a.width+xx]&255,vb=b.gray[v*b.width+u]&255;sa+=va;sb+=vb;saa+=va*va;sbb+=vb*vb;sab+=va*vb;n++;}double den=Math.sqrt(Math.max(0,(n*saa-sa*sa)*(n*sbb-sb*sb)));return n>40&&den>100?(float)((n*sab-sa*sb)/den):-1;}
 public static Result resolve(ClipCache c,FocusEdits edits)throws Exception{return resolve(new Source(){public int size(){return c.times.size();}public ClipCache.Feature feature(int i)throws Exception{return c.feature(i);}},edits);}
 public static Result resolve(Source source,FocusEdits edits)throws Exception{Result r=new Result(source.size());ClipCache.Feature previous=null,reference=null;int key=0,mode=FocusEdits.AUTO;float x=.5f,y=.5f,rx=x,ry=y,target=.5f,current=.5f,from=.5f,duration=0;long start=0,pendingStart=0;Subject pending=null;boolean pulling=false,strong=true;float handleA=0,handleB=1;long lostSince=-1;List<Subject> lastSubjects=new ArrayList<>();int nextId=1,selectedId=-1;
 for(int i=0;i<source.size();i++){ClipCache.Feature f=source.feature(i);boolean cut=previous==null||previous.scene!=f.scene;r.cut[i]=cut;boolean change=false;float seconds=edits.duration;List<Subject> subjects=subjects(f);HashSet<Integer> used=new HashSet<>();for(Subject v:subjects){Subject match=null;float bestCost=.06f;for(Subject old:lastSubjects){float cost=dist(v.x,v.y,old)+.3f*Math.abs(v.d-old.d);if(!cut&&!used.contains(old.id)&&cost<bestCost){bestCost=cost;match=old;}}v.id=match==null?nextId++:match.id;used.add(v.id);}r.candidates[i]=subjects;lastSubjects=subjects;
 if(cut){selectedId=-1;mode=FocusEdits.AUTO;Subject s=subjects.get(0);x=s.x;y=s.y;target=s.d;reference=null;pending=null;pulling=false;}
 while(key<edits.keys.size()&&edits.keys.get(key).time<=f.time){FocusEdits.Key k=edits.keys.get(key++);selectedId=-1;mode=k.mode;x=k.x;y=k.y;target=k.depth;seconds=k.seconds;strong=k.strong;handleA=k.outHandle;handleB=k.inHandle;lostSince=-1;reference=null;pending=null;change=true;}
 float confidence=1;
 if(mode==FocusEdits.TRACK){Subject selected=null;if(selectedId<0){for(Subject v:subjects)if(v.score>1&&dist(x,y,v)<.025&&(selected==null||dist(x,y,v)<dist(x,y,selected)))selected=v;if(selected!=null)selectedId=selected.id;}else for(Subject v:subjects)if(v.id==selectedId)selected=v;
 if(selected!=null){x=selected.x;y=selected.y;target=selected.d;reference=f;rx=x;ry=y;if(!strong){Subject challenger=subjects.get(0);if(challenger.id!=selected.id&&challenger.score>selected.score*1.8){if(pending==null||pending.id!=challenger.id)pendingStart=f.time;pending=challenger;if(f.time-pendingStart>1000000){mode=FocusEdits.AUTO;change=true;x=challenger.x;y=challenger.y;target=challenger.d;pending=null;}}else pending=null;}}}

 if(mode==FocusEdits.TRACK){if(reference==null){reference=f;rx=x;ry=y;target=f.at(x,y);}else{int ax=Math.round(rx*(reference.width-1)),ay=Math.round(ry*(reference.height-1)),cx=Math.round(x*(f.width-1)),cy=Math.round(y*(f.height-1)),bx=cx,by=cy;float best=-2;for(int v=Math.max(0,cy-14);v<=Math.min(f.height-1,cy+14);v++)for(int u=Math.max(0,cx-14);u<=Math.min(f.width-1,cx+14);u++){float value=score(reference,ax,ay,f,u,v)-.0001f*((u-cx)*(u-cx)+(v-cy)*(v-cy));if(value>best){best=value;bx=u;by=v;}}confidence=Math.max(0,best);if(best>.5){x=bx/(float)(f.width-1);y=by/(float)(f.height-1);target=f.at(x,y);rx=x;ry=y;reference=f;}}}
 if(mode==FocusEdits.TRACK&&!strong){if(confidence<.5){if(lostSince<0)lostSince=f.time;if(f.time-lostSince>800000){mode=FocusEdits.AUTO;change=true;}}else lostSince=-1;}
 else if(mode==FocusEdits.AUTO){Subject near=subjects.get(0);for(Subject s:subjects)if(dist(x,y,s)<dist(x,y,near))near=s;Subject best=subjects.get(0);boolean lost=dist(x,y,near)>.08;if(lost){near=best;change=true;}if(best!=near&&best.score>near.score*1.5){if(pending==null||dist(pending.x,pending.y,best)>.025)pendingStart=f.time;pending=best;if(f.time-pendingStart>650000){near=best;change=true;pending=null;}}else pending=null;x=near.x;y=near.y;target=near.d;}
 if(cut){current=target;pulling=false;}else if(change){from=current;start=f.time;duration=seconds;pulling=seconds>0;if(!pulling)current=target;}
 if(!cut){if(pulling){float t=(f.time-start)/Math.max(1,duration*1000000);current=from+(target-from)*curve(t,handleA,handleB);if(t>=1)pulling=false;}else if(mode==FocusEdits.FIXED)current=target;else{float dt=(f.time-previous.time)/1000000f,tau=Math.abs(target-current)>.05?.035f:.08f;current+=(target-current)*(1-(float)Math.exp(-dt/tau));}}
 r.focus[i]=current;r.x[i]=x;r.y[i]=y;r.confidence[i]=confidence;previous=f;
 }return r;}
}
